{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    mins = [seg['minimum'] for seg in segments]
    caps = [seg['capacity'] for seg in segments]
    sum_min = sum(mins)
    sum_cap = sum(caps)
    if budget < sum_min or budget > sum_cap:
        raise ValueError('Budget out of bounds')
    allocations = mins[:]
    remaining = budget - sum_min
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i in range(n):
            if allocations[i] >= caps[i]:
                continue
            score = segments[i]['importance'] / (allocations[i] + 1)
            if score > best_score:
                best_score = score
                best_idx = i
        if best_idx == -1:
            break
        allocations[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    return {'allocations': allocations, 'by_name': by_name, 'total': budget}"
}
